#!/usr/bin/env bash
# Replace the placeholder IDL with the real one generated by the program build.
#
# The Trana protocol repo does not commit its IDL. Generate it from the
# freight_delay Anchor workspace, then copy it over this file:
#
#   cd <trana-protocol-repo>/freight_delay
#   anchor build
#   cp target/idl/freight_delay.json <this-repo>/src/program/idl.json
#
# After replacing, verify:
#   1. `address` matches the deployed program ID.
#   2. Instruction account lists match src/program/client.ts
#      (especially settlePolicy's beneficiary account).
#   3. `bun run build` and `bun run test` still pass.
set -euo pipefail

echo "This script documents the IDL refresh; it does not fetch anything itself."
echo "See the header comment for the manual steps."
